import{_ as a,o as r,c as o,a2 as i}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Lumberjacking","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/lumberjacking.md","filePath":"es/guide/professions/lumberjacking.md"}'),s={name:"es/guide/professions/lumberjacking.md"};function n(l,e,t,c,d,p){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="lumberjacking" tabindex="-1">Lumberjacking <a class="header-anchor" href="#lumberjacking" aria-label="Enlace permanente a &quot;Lumberjacking&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Esta página describe el rediseño previsto, no mecánicas confirmadas en el juego. <strong>Implementación/disponibilidad:</strong> no establecida para este rediseño. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-08 frente a la <a href="/Syrolands-Public/es/game-design/professions/lumberjacking.html">especificación completa del diseño</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Lumberjacking combina conocimiento forestal, selección y tala.</li><li>Un árbol caído podría obstruir una ruta; las protecciones y reglas de recuperación siguen sin resolverse.</li><li>Las mejores decisiones deberían proporcionar madera útil y reducir desperdicios, sin recompensar la tala indiscriminada.</li></ul><h2 id="what-it-does" tabindex="-1">Qué hace <a class="header-anchor" href="#what-it-does" aria-label="Enlace permanente a &quot;Qué hace&quot;">​</a></h2><p>Lumberjacking debería recompensar el conocimiento forestal y la selección de madera, además de golpear cualquier árbol para obtener troncos. Especie, madurez, salud y calidad aproximada de la madera pueden orientar dónde y cómo recolectar.</p><h2 id="why-take-it-into-the-field" tabindex="-1">¿Por qué llevarlo a una expedición? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Enlace permanente a &quot;¿Por qué llevarlo a una expedición?&quot;">​</a></h2><p>Los árboles talados podrían ocupar varias casillas y alterar temporalmente rutas o pasos estrechos. La tala controlada podría tener usos en combate o asedios; los puentes improvisados son solo una posible aplicación posterior. Las protecciones del mundo, los peligros y la recuperación deben definirse antes de que esto se convierta en reglas jugables.</p><h2 id="learning-and-specialization" tabindex="-1">Aprendizaje y especialización <a class="header-anchor" href="#learning-and-specialization" aria-label="Enlace permanente a &quot;Aprendizaje y especialización&quot;">​</a></h2><p>El Forester’s Journal registra especies, estado de los árboles y ecología regional. La tala rápida, la tala controlada y el corte selectivo son enfoques candidatos. La selección debería ahorrar tiempo, reducir el desgaste de herramientas o recuperar más madera útil, dando motivos para evitar la tala indiscriminada.</p><h2 id="progression-and-related-crafts" tabindex="-1">Progresión y oficios relacionados <a class="header-anchor" href="#progression-and-related-crafts" aria-label="Enlace permanente a &quot;Progresión y oficios relacionados&quot;">​</a></h2><p>Los <a href="/Syrolands-Public/es/guide/professions/overview.html">principios compartidos de aprendizaje y producción</a> se aplican cuando corresponda. Más conocimiento y habilidad deberían mejorar la selección y el rendimiento de los materiales. <a href="/Syrolands-Public/es/guide/professions/carpentry.html">Carpentry</a> utiliza la madera, mientras que Camping y <a href="/Syrolands-Public/es/guide/professions/cooking.html">Cooking</a> conectan con el combustible. La regeneración y los efectos exactos de la sobreexplotación siguen abiertos.</p><p><a href="/Syrolands-Public/es/guide/professions/overview.html">Todas las profesiones</a> · <a href="/Syrolands-Public/es/game-design/professions/lumberjacking.html">Especificación completa del diseño</a></p>',13)])])}const g=a(s,[["render",n]]);export{m as __pageData,g as default};
